/// <summary>
/// Intialize
/// </summary>
public void init()
{
    next init();

    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {
        if (AVADAIParameters::find().Enabled == NoYes::Yes)               
        {                           
            if (AVADAIArchiveFormConfig::existForm(this.name()))
            {
                AVADAIFormRunController dmsFormRun = AVADAIFormRunController::construct(this);
                dmsFormRun.addDMSButtonGroupAndButton();
            }
        }
    }
}
